		var sources = Enumerable.Range( 0, 256 ).Select( value => Encoding.ASCII.GetBytes( String.Concat( @"(*MARK:\x", value.ToString( "X2" ), ")(A)" ) ) ).ToArray();
		var references = sources.Select( source => Reference( source, true, mode ) ).ToArray();
		var subject = "A"u8.ToArray();
		for ( var value = 0; value < sources.Length; value++ ) {
			var visible = value == 0 ? Array.Empty<byte>() : ( mode & 5 ) != 0 ? Encoding.UTF8.GetBytes( ( (char)value ).ToString() ) : new[] { (byte)value };
			AssertLiteral( references[value], subject, "0:1,0:1", Convert.ToHexString( visible ) );
			Compare( references[value], subject, 0, Compile( sources[value], Options( true, mode ) ).Match( subject ), $"label octet {value}" );
		}
	}

	[Theory]
	[InlineData( "(*LF)", 0 )]
	[InlineData( "(*LF)", 7 )]
	[InlineData( "(*ANYCRLF)", 0 )]
	[InlineData( "(*ANYCRLF)", 7 )]
	[InlineData( "(*CR)", 0 )]
	[InlineData( "(*CR)", 7 )]
	[InlineData( "(*NUL)", 0 )]
	[InlineData( "(*NUL)", 7 )]
	[InlineData( "(*CRLF)", 0 )]
	[InlineData( "(*CRLF)", 7 )]
	[InlineData( "(*ANY)", 0 )]
	[InlineData( "(*ANY)", 7 )]
	public void EveryOffsetRetainsSharedNamedCutsNewlinesAndInvalidUtfFragments( string newline, int mode ) {
		var sources = OffsetBodies.Select( body => Encoding.ASCII.GetBytes( String.Concat( newline, body ) ) ).ToArray();
		var references = sources.Select( source => Reference( source, true, mode ) ).ToArray();
		for ( var index = 0; index < sources.Length; index++ ) {
			var compiled = Compile( sources[index], Options( true, mode ) );
			foreach ( var hex in new[] { "", "41", "4142", "414142", "41434142", "0D0A41", "0D0A4142", "0B0D0A41", "0A41", "E280A841", "C2850A41", "FF41", "E280FF41", "E280A841FF42", "410D0A", "00FF41" } ) {
				var subject = Convert.FromHexString( hex );
				for ( var offset = 0; offset <= subject.Length; offset++ ) {
					Compare( references[index], subject, offset, compiled.Match( subject, offset ), $"{newline}/{index}/{hex}/{offset}/{mode}" );
				}
			}
		}
	}

	[Fact]
	public void DecodedLabelsRetainCanonicalWorkLimitsAndCancellation() {
		var sources = new[] { Encoding.ASCII.GetBytes( @"(*MARK:\x4b)(A|AA)+B" ), Encoding.ASCII.GetBytes( "(*MARK:K)(A|AA)+B" ) };
		var references = sources.Select( source => Reference( source, true, 0 ) ).ToArray();
		var subject = "AAAB"u8.ToArray();
		foreach ( var reference in references ) { AssertLiteral( reference, subject, "0:4,2:1", "4B" ); }
		var steps = new List<int>();
		var canonical = new List<int>();
		var options = Options( true, 0 ) with { WorkObserver = steps.Add };
		Compare( references[0], subject, 0, Compile( sources[0], options ).Match( subject ), "decoded label work" );
		Compare( references[1], subject, 0, Compile( sources[1], Options( true, 0 ) with { WorkObserver = canonical.Add } ).Match( subject ), "raw canonical work" );
		Assert.Equal( canonical, steps );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Assert.True( steps.Count > 2 );
		var limited = Compile( sources[0], options with { MatchWorkLimit = steps.Count - 1 } ).Match( subject );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		Assert.Null( limited.Match );
		using var cancellation = new CancellationTokenSource();
		var compiled = Compile( sources[0], options with { WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } } } );
		Assert.Throws<OperationCanceledException>( () => compiled.Match( subject, 0, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( sources[0], options, cancellation.Token ) );
	}

	[Fact]
	public void DecodedUtfNamesAndCapturedMatchesOwnSourceAndOptions() {
		var source = Encoding.UTF8.GetBytes( @"(?<x>A)(*MARK:\Q)é\E)\k<x>" );
		var subject = "AA"u8.ToArray();
		var reference = Reference( source, true, 3 );
		AssertLiteral( reference, subject, "0:2,0:1", "29C3A9" );
		var options = Options( true, 3 );
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "AltVerbNames" )?.SetValue( options, false );
		Compare( reference, subject, 0, compiled.Match( subject ), "owned UTF label" );
	}

	[Fact]
	public void NameDecodingRetainsSharedStructuralLimits() {
		var patterns = new[] {
			String.Concat( String.Concat( Enumerable.Repeat( "()", 256 ) ), @"(*MARK:\x4b)A" ),
			String.Concat( String.Concat( Enumerable.Repeat( "()", 257 ) ), @"(*MARK:\x4b)A" ),
			String.Concat( new string( '(', 257 ), @"(*MARK:\x4b)A", new string( ')', 257 ) ), @"(*MARK:\x4b)A{4096}"
		};
		var references = patterns.Select( pattern => Reference( Encoding.ASCII.GetBytes( pattern ), true, 0 ) ).ToArray();
		Compare( references[0], "A"u8.ToArray(), 0, Compile( Encoding.ASCII.GetBytes( patterns[0] ), Options( true, 0 ) ).Match( "A"u8.ToArray() ), "named full capture capacity" );
		var codes = new[] { PcreByteDiagnosticCode.PatternCaptureLimitExceeded, PcreByteDiagnosticCode.PatternDepthLimitExceeded, PcreByteDiagnosticCode.PatternRepeatLimitExceeded };
		for ( var index = 1; index < patterns.Length; index++ ) {
			var actual = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( patterns[index] ), Options( true, 0 ) );
			Assert.Equal( codes[index - 1], actual.Diagnostic?.Code );
			Assert.Null( actual.Pattern );
		}
	}

	[Fact]
	public void CallerModeGuardsPrecedeNameErrorsWhileCodeUnitTokensRemainInvalidNameData() {
		var sources = new[] { Encoding.ASCII.GetBytes( @"(*MARK:\d)A" ), Encoding.ASCII.GetBytes( @"(*UCP)(*MARK:\d)A" ), Encoding.ASCII.GetBytes( @"(*MARK:\C)A" ) };
		var modes = new[] { 1, 0, 2048 };
		var flags = new uint[] { 0x1000, 0x800, 0 };
		var nativeCodes = new[] { 174, 175, 140 };
		var nativeOffsets = new[] { 0, 6, 9 };
		var offsets = new[] { 0, 6, 7 };
		var native = sources.Select( ( source, index ) => Assert.Throws<PcrePatternException>( () => Reference( source, true, modes[index], flags[index] ) ) ).ToArray();
		for ( var index = 0; index < sources.Length; index++ ) {
			Assert.Equal( nativeCodes[index], (int)native[index].ErrorCode );
			Assert.EndsWith( $" at offset {nativeOffsets[index]}.", native[index].Message );
		}
		var options = new[] { Options( true, 1 ) with { NeverUtf = true }, Options( true, 0 ) with { NeverUcp = true }, Options( true, 2048 ) };
		for ( var index = 0; index < sources.Length; index++ ) {
			var actual = PcreByteCompiler.Compile( sources[index], options[index] );
			Assert.Equal( PcreByteDiagnosticCode.InvalidSyntax, actual.Diagnostic?.Code );
			Assert.Equal( offsets[index], actual.Diagnostic?.ByteOffset );
			if ( index < 2 ) { Assert.Contains( "disabled by the caller", actual.Diagnostic!.Message ); }
			else { Assert.DoesNotContain( "disabled by the caller", actual.Diagnostic!.Message ); }
			Assert.Null( actual.Pattern );
		}
		var literal = Encoding.ASCII.GetBytes( @"(*MARK:\u{5c}C)A" );
		var subject = "A"u8.ToArray();
		var reference = Reference( literal, true, 128 | 2048 );
		AssertLiteral( reference, subject, "0:1", "5C43" );
		Compare( reference, subject, 0, Compile( literal, Options( true, 128 | 2048 ) ).Match( subject ), "decoded slash is not a token" );
	}

	[Fact]
	public void WholePatternUtfValidationStillPrecedesTheNameGrammar() {
		var prefix = Encoding.ASCII.GetBytes( @"(*MARK:\d)A" );
		var source = prefix.Concat( new byte[] { 0xFF } ).ToArray();
		foreach ( var enabled in new[] { false, true } ) {
			var native = Assert.Throws<PcrePatternException>( () => Reference( source, enabled, 3 ) );
			Assert.Equal( -23, (int)native.ErrorCode );
			Assert.EndsWith( $" at offset {prefix.Length}.", native.Message );
			var actual = PcreByteCompiler.Compile( source, Options( enabled, 3 ) );
			Assert.Equal( PcreByteDiagnosticCode.InvalidUtf8Pattern, actual.Diagnostic?.Code );
			Assert.Equal( prefix.Length, actual.Diagnostic?.ByteOffset );
			Assert.Null( actual.Pattern );
		}
	}

	[Fact]
	public void AlternateNamesDoNotCreateAPatternDirective() {
		var source = "(*ALT_VERBNAMES)A"u8.ToArray();
		foreach ( var enabled in new[] { false, true } ) {
			Assert.Throws<PcrePatternException>( () => Reference( source, enabled, 0 ) );
			var actual = PcreByteCompiler.Compile( source, Options( enabled, 0 ) );
			Assert.Equal( PcreByteDiagnosticCode.UnsupportedSyntax, actual.Diagnostic?.Code );
			Assert.Equal( 0, actual.Diagnostic?.ByteOffset );
			Assert.Null( actual.Pattern );
		}
	}

	[Fact]
	public void LocalNameQuotingDoesNotQuoteFollowingRegexGroupsOrEnableOrdinaryEscapedUtf() {
		var source = Encoding.ASCII.GetBytes( @"(*MARK:\Q)\E)(A)" );
		var reference = Reference( source, true, 0 );
		var subject = "A"u8.ToArray();
		AssertLiteral( reference, subject, "0:1,0:1", "29" );
		Compare( reference, subject, 0, Compile( source, Options( true, 0 ) ).Match( subject ), "local name quoting" );
		var escaped = Encoding.UTF8.GetBytes( @"\é" );
		AssertLiteral( Reference( escaped, true, 3 ), "é"u8.ToArray(), "0:2", "" );
		var actual = PcreByteCompiler.Compile( escaped, Options( true, 3 ) );
		Assert.Equal( PcreByteDiagnosticCode.UnsupportedSyntax, actual.Diagnostic?.Code );
		Assert.Equal( 0, actual.Diagnostic?.ByteOffset );
		Assert.Null( actual.Pattern );
	}

	private static readonly string[] OffsetBodies = [@"(*MARK:\x4b)(A)", @"\G(*MARK:\x4b)(A)", @"(*MARK:\x4b)A(*SKIP:K)B|A", @"(*MARK:K)A(*SKIP:\E)B|A", @"(*MARK:\E)A(*SKIP:\E)B|A", @"(*MARK:old)A(*PRUNE:\E)", @"(*MARK:\Q)\E)(A)", @"(?m)^(*MARK:\x4b)A"];
	private static PcreByteOptions Options( bool enabled, int mode ) {
		var options = new PcreByteOptions { Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0, MatchInvalidUtf = ( mode & 4 ) != 0,
			Caseless = ( mode & 8 ) != 0, Extended = ( mode & 16 ) != 0, ExtendedMore = ( mode & 32 ) != 0, AltBsux = ( mode & 64 ) != 0,
			ExtraAltBsux = ( mode & 128 ) != 0, PythonOctal = ( mode & 256 ) != 0, NoBackslashZero = ( mode & 512 ) != 0,
			EscapedCrIsLf = ( mode & 1024 ) != 0, NeverBackslashC = ( mode & 2048 ) != 0 };
		// Keep tests-only RED executable before the new caller property exists.
		if ( enabled ) { typeof( PcreByteOptions ).GetProperty( "AltVerbNames" )?.SetValue( options, true ); }
		return options;
	}
	private static PcreRegex8Bit Reference( byte[] source, bool enabled, int mode, uint flags = 0 ) => new(
		source, Encoding.UTF8, new PcreRegexSettings {
			Options = PcreOptions.Compiled | (PcreOptions)( flags | ( enabled ? 0x400000u : 0u )
				| ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u ) | ( ( mode & 4 ) != 0 ? 0x4000000u : 0u )
				| ( ( mode & 8 ) != 0 ? 8u : 0u ) | ( ( mode & 48 ) != 0 ? 0x80u : 0u ) | ( ( mode & 32 ) != 0 ? 0x1000000u : 0u )
				| ( ( mode & 64 ) != 0 ? 2u : 0u ) | ( ( mode & 2048 ) != 0 ? 0x100000u : 0u ) ),
			ExtraCompileOptions = (PcreExtraCompileOptions)( ( ( mode & 128 ) != 0 ? 0x20 : 0 ) | ( ( mode & 256 ) != 0 ? 0x2000 : 0 )
				| ( ( mode & 512 ) != 0 ? 0x4000 : 0 ) | ( ( mode & 1024 ) != 0 ? 0x10 : 0 ) ), ParensLimit = 512
		} );
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, $"{Encoding.UTF8.GetString( source )}: {actual.Diagnostic?.Message}" );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertLiteral( PcreRegex8Bit reference, byte[] subject, string spans, string mark ) {
		var match = reference.Match( subject );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Equal( mark, Convert.ToHexString( match.Mark.ToArray() ) );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.Length}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.True( ( expected.Success ? expected.Index : -1 ) == ( actual.Match?.ByteIndex ?? -1 ), context );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.Length, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.Length ) : null, actual.Match.Captures[group] );
		}
	}
}
